    private static Order LargeOrderOf(CustomerType customer, decimal subtotal) =>
        new(customer, [new OrderLine("A", subtotal, 1)]);

    [Fact]
    public void Order_just_below_threshold_gets_no_extra_discount() =>
        Assert.Equal(999.99m, PriceCalculator.Total(LargeOrderOf(CustomerType.Regular, 999.99m)));

    [Fact]
    public void Regular_customer_gets_three_percent_off_at_threshold() =>
        Assert.Equal(970m, PriceCalculator.Total(LargeOrderOf(CustomerType.Regular, 1000m)));

    [Fact]
    public void Loyal_customer_gets_three_percent_off_after_loyalty_discount() =>
        // 2000 - 5% = 1900, then 3% off 1900 = 1843
        Assert.Equal(1843m, PriceCalculator.Total(LargeOrderOf(CustomerType.Loyal, 2000m)));
}

